 28 | export function project(x, y, z = 0) {
 29 |   return { x: x * TILE_SIZE, y: y * TILE_SIZE - z * TILE_SIZE * 0.5 };
 30 | }
 31 | 
 32 | export function unproject(x, y) {
 33 |   return { x: x / TILE_SIZE, y: y / TILE_SIZE };
 34 | }
 35 | 
 36 | export function isWalkable(x, y, objects = OBJECTS) {
 37 |   if (!Number.isFinite(x) || !Number.isFinite(y)) return false;
 38 |   const r = FOUNDER_RADIUS;
 39 |   if (x < r || y < r || x > ROOM.width - r || y > ROOM.depth - r) return false;
 40 |   const pad = 0.05;
 41 |   return !objects.some((o) => x > o.x - pad && x < o.x + o.w + pad && y > o.y - pad && y < o.y + o.d + pad);
 42 | }
 43 | 
 44 | export function canTravel(from, to, objects = OBJECTS) {
 45 |   const steps = Math.max(1, Math.ceil(Math.hypot(to.x - from.x, to.y - from.y) / 0.07));
 46 |   for (let i = 0; i <= steps; i++) {
 47 |     const t = i / steps;
 48 |     if (!isWalkable(from.x + (to.x - from.x) * t, from.y + (to.y - from.y) * t, objects)) return false;
 49 |   }
 50 |   return true;
 51 | }
 52 | 
 53 | // A* on a quarter-tile grid, followed by collision-tested line-of-sight smoothing.
 54 | export function nearestWalkable(tx, ty, objects = OBJECTS) {
 55 |   if (isWalkable(tx, ty, objects)) return { x: tx, y: ty };
 56 |   // Spiral outward in quarter-tile steps until we find a walkable point
 57 |   const step = 0.25;
 58 |   for (let r = step; r <= 3; r += step) {
 59 |     let best = null, bestDist = Infinity;
 60 |     const n = Math.ceil((r * 2) / step);
 61 |     for (let i = 0; i <= n; i++) {
 62 |       const t = i / n;
 63 |       for (const [cx, cy] of [
 64 |         [tx - r + t * r * 2, ty - r],
 65 |         [tx + r, ty - r + t * r * 2],
 66 |         [tx + r - t * r * 2, ty + r],
 67 |         [tx - r, ty + r - t * r * 2],
 68 |       ]) {
 69 |         const rx = Math.round(cx / step) * step;
 70 |         const ry = Math.round(cy / step) * step;
 71 |         if (!isWalkable(rx, ry, objects)) continue;
 72 |         const d = Math.hypot(rx - tx, ry - ty);
 73 |         if (d < bestDist) { best = { x: rx, y: ry }; bestDist = d; }
 74 |       }
 75 |     }
 76 |     if (best) return best;
 77 |   }
 78 |   return null;
 79 | }
