223 | // ── Parkour: attempt to vault over a nearby vaultable object ──────────────
224 | function tryVault() {
225 |   if (jumpState || vaultCooldown > 0) return; // already airborne or cooling down
226 |   if (state.energy < 6) { toast('Too drained to jump. Grab a coffee first. ☕'); return; }
227 |   const isSprintJump = (sprinting || dashLocked) && state.energy > 1;
228 |   // Sprint-jump carries further: scale reach and landing distance
229 |   const sprintMult = isSprintJump ? 1.6 : 1.0;
230 |   // Look for a vaultable object in the direction of movement, within reach
231 |   const reach = 2.0 * sprintMult;
232 |   const fx = state.founder.x + direction.x * reach;
233 |   const fy = state.founder.y + direction.y * reach;
234 |   const target = OBJECTS.find(o =>
235 |     VAULTABLE_TYPES.has(o.type) &&
236 |     fx > o.x - 0.4 && fx < o.x + o.w + 0.4 &&
237 |     fy > o.y - 0.4 && fy < o.y + o.d + 0.4
238 |   );
239 |   if (!target) {
240 |     // No object nearby — do a free hop: costs stamina and lands with a stumble
241 |     const hopDist = 1.0 * sprintMult;
242 |     const toX = state.founder.x + direction.x * hopDist;
243 |     const toY = state.founder.y + direction.y * hopDist;
244 |     changeEnergy(-4);
245 |     jumpState = { t: 0, duration: 0.28, fromX: state.founder.x, fromY: state.founder.y, toX, toY, peakHeight: 1.8 + (isSprintJump ? 0.6 : 0), vaultObject: null, freeHop: true, sprintJump: isSprintJump };
246 |     return;
247 |   }
248 |   // Land on the other side: project from object center along movement direction
249 |   const objCx = target.x + target.w / 2;
250 |   const objCy = target.y + target.d / 2;
251 |   const halfExtent = Math.abs(direction.x) > Math.abs(direction.y)
252 |     ? target.w / 2
253 |     : target.d / 2;
254 |   const landDist = (halfExtent + 0.65) * sprintMult;
255 |   const landX = objCx + direction.x * landDist;
256 |   const landY = objCy + direction.y * landDist;
257 |   // Check landing spot is walkable
258 |   if (!isWalkable(landX, landY)) { toast('Nowhere to land! Clear a path first.'); return; }
259 |   // Scale jump height and duration with table span
260 |   const tableSpan = Math.max(target.w, target.d);
261 |   const peakH = (2.5 + tableSpan * 0.5) * (isSprintJump ? 1.25 : 1);
262 |   const dur = (0.30 + tableSpan * 0.06) * (isSprintJump ? 0.8 : 1); // sprint-jump is snappier
263 |   const isShortcutTable = target.type === 'table-vault';
264 |   changeEnergy(isShortcutTable ? -6 : -10);
265 |   jumpState = { t: 0, duration: dur, fromX: state.founder.x, fromY: state.founder.y, toX: landX, toY: landY, peakHeight: peakH, vaultObject: target, sprintJump: isSprintJump };
266 |   playSound('coffee');
267 | }
