269 | // ── Parkour: blink dash — instant short-range teleport forward ───────────
270 | function tryBlink() {
271 |   if (blinkCooldown > 0) { toast('⚡ Blink recharging…'); return; }
272 |   if (state.energy < 8) { toast('Too drained to blink. Grab a coffee first. ☕'); return; }
273 |   if (paused || dialog.open) return;
274 | 
275 |   // Step forward in direction as far as walkable, up to BLINK_DIST tiles
276 |   const BLINK_DIST = 3.0;
277 |   const STEPS = 24; // resolution of the walk-forward check
278 |   let landX = state.founder.x;
279 |   let landY = state.founder.y;
280 |   for (let i = 1; i <= STEPS; i++) {
281 |     const t = (i / STEPS) * BLINK_DIST;
282 |     const cx = state.founder.x + direction.x * t;
283 |     const cy = state.founder.y + direction.y * t;
284 |     if (!isWalkable(cx, cy)) break;
285 |     landX = cx;
286 |     landY = cy;
287 |   }
288 | 
289 |   const dist = Math.hypot(landX - state.founder.x, landY - state.founder.y);
290 |   if (dist < 0.25) { toast('Nowhere to blink — something is blocking the way.'); return; }
