504 |   /* ── Character: pixel-art top-down sprite ────────────────────────────── */
505 |   character(founder,dir,moving,time,jumpHeight=0,isSprinting=false){
506 |     const ctx=this.ctx, S=this.scale, T=TILE_SIZE*S;
507 |     const p=this.sp(founder.x,founder.y);
508 |     // Jump: lift the sprite up (in isometric: up-left = higher z)
509 |     const jumpOffsetY = Math.round(jumpHeight * S * TILE_SIZE * 0.5 / TILE_SIZE * 2);
510 |     const cx=Math.round(p.x+T/2), cy=Math.round(p.y+T/2) - jumpOffsetY;
511 | 
512 |     /* walk frame toggles every 180ms — faster when sprinting */
513 |     const walkInterval = isSprinting ? 100 : 180;
514 |     const frame=(moving&&!this.reducedMotion)?Math.floor(time/walkInterval)%2:0;
515 | 
516 |     /* dominant facing direction */
517 |     const facing=Math.abs(dir.x)>=Math.abs(dir.y)
518 |       ?(dir.x>0?'r':'l')
519 |       :(dir.y>0?'d':'u');
520 | 
521 |     /* helper: draw one "pixel" of the sprite, offset from character center */
522 |     const r=(color,dx,dy,w,h)=>
523 |       px(ctx,color,cx+Math.round(dx*S),cy+Math.round(dy*S),Math.round(w*S)||1,Math.round(h*S)||1);
524 | 
525 |     /* ── ground shadow (always on floor, not lifted with character) ── */
