 38 | export function isWalkable(x, y, objects = OBJECTS) {
 39 |   if (!Number.isFinite(x) || !Number.isFinite(y)) return false;
 40 |   const r = FOUNDER_RADIUS;
 41 |   if (x < r || y < r || x > ROOM.width - r || y > ROOM.depth - r) return false;
 42 |   const pad = 0.05;
 43 |   return !objects.some((o) => x > o.x - pad && x < o.x + o.w + pad && y > o.y - pad && y < o.y + o.d + pad);
 44 | }
