 46 | export function canTravel(from, to, objects = OBJECTS) {
 47 |   const steps = Math.max(1, Math.ceil(Math.hypot(to.x - from.x, to.y - from.y) / 0.07));
 48 |   for (let i = 0; i <= steps; i++) {
 49 |     const t = i / steps;
 50 |     if (!isWalkable(from.x + (to.x - from.x) * t, from.y + (to.y - from.y) * t, objects)) return false;
 51 |   }
 52 |   return true;
 53 | }
