 55 | // A* on a quarter-tile grid, followed by collision-tested line-of-sight smoothing.
 56 | export function nearestWalkable(tx, ty, objects = OBJECTS) {
 57 |   if (isWalkable(tx, ty, objects)) return { x: tx, y: ty };
 58 |   // Spiral outward in quarter-tile steps until we find a walkable point
 59 |   const step = 0.25;
 60 |   for (let r = step; r <= 3; r += step) {
 61 |     let best = null, bestDist = Infinity;
 62 |     const n = Math.ceil((r * 2) / step);
 63 |     for (let i = 0; i <= n; i++) {
 64 |       const t = i / n;
 65 |       for (const [cx, cy] of [
 66 |         [tx - r + t * r * 2, ty - r],
 67 |         [tx + r, ty - r + t * r * 2],
 68 |         [tx + r - t * r * 2, ty + r],
 69 |         [tx - r, ty + r - t * r * 2],
 70 |       ]) {
 71 |         const rx = Math.round(cx / step) * step;
 72 |         const ry = Math.round(cy / step) * step;
 73 |         if (!isWalkable(rx, ry, objects)) continue;
 74 |         const d = Math.hypot(rx - tx, ry - ty);
 75 |         if (d < bestDist) { best = { x: rx, y: ry }; bestDist = d; }
 76 |       }
 77 |     }
 78 |     if (best) return best;
 79 |   }
 80 |   return null;
 81 | }
