255 | // ── Parkour: attempt to vault over a nearby vaultable object ──────────────
256 | function tryVault() {
257 |   if (jumpState || vaultCooldown > 0) return; // already airborne or cooling down
258 |   if (state.energy < 6) { toast('Too drained to jump. Grab a coffee first. ☕'); return; }
259 |   const isSprintJump = (sprinting || dashLocked) && state.energy > 1;
260 |   // Sprint-jump carries further: scale reach and landing distance
261 |   const sprintMult = isSprintJump ? 1.6 : 1.0;
262 |   // Look for a vaultable object in the direction of movement, within reach
263 |   const reach = 2.0 * sprintMult;
264 |   const fx = state.founder.x + direction.x * reach;
265 |   const fy = state.founder.y + direction.y * reach;
266 |   const target = OBJECTS.find(o =>
267 |     VAULTABLE_TYPES.has(o.type) &&
268 |     fx > o.x - 0.4 && fx < o.x + o.w + 0.4 &&
269 |     fy > o.y - 0.4 && fy < o.y + o.d + 0.4
270 |   );
271 |   if (!target) {
272 |     // No object nearby — do a free hop: costs stamina and lands with a stumble
273 |     const hopDist = 1.0 * sprintMult;
274 |     const toX = state.founder.x + direction.x * hopDist;
275 |     const toY = state.founder.y + direction.y * hopDist;
276 |     changeEnergy(-4);
277 |     jumpState = { t: 0, duration: 0.28, fromX: state.founder.x, fromY: state.founder.y, toX, toY, peakHeight: 1.8 + (isSprintJump ? 0.6 : 0), vaultObject: null, freeHop: true, sprintJump: isSprintJump };
278 |     return;
279 |   }
280 |   // Land on the other side: project from object center along movement direction
281 |   const objCx = target.x + target.w / 2;
282 |   const objCy = target.y + target.d / 2;
283 |   const halfExtent = Math.abs(direction.x) > Math.abs(direction.y)
284 |     ? target.w / 2
285 |     : target.d / 2;
286 |   const landDist = (halfExtent + 0.65) * sprintMult;
287 |   const landX = objCx + direction.x * landDist;
288 |   const landY = objCy + direction.y * landDist;
289 |   // Check landing spot is walkable
290 |   if (!isWalkable(landX, landY)) { toast('Nowhere to land! Clear a path first.'); return; }
291 |   // Scale jump height and duration with table span
292 |   const tableSpan = Math.max(target.w, target.d);
293 |   const peakH = (2.5 + tableSpan * 0.5) * (isSprintJump ? 1.25 : 1);
294 |   const dur = (0.30 + tableSpan * 0.06) * (isSprintJump ? 0.8 : 1); // sprint-jump is snappier
