301 | // ── Parkour: blink dash — instant short-range teleport forward ───────────
302 | function tryBlink() {
303 |   if (blinkCooldown > 0) { toast('⚡ Blink recharging…'); return; }
304 |   if (state.energy < 8) { toast('Too drained to blink. Grab a coffee first. ☕'); return; }
305 |   if (paused || dialog.open) return;
