313 |     const t = (i / STEPS) * BLINK_DIST;
314 |     const cx = state.founder.x + direction.x * t;
315 |     const cy = state.founder.y + direction.y * t;
316 |     if (!isWalkable(cx, cy)) break;
317 |     landX = cx;
318 |     landY = cy;
319 |   }
