/* ── Character: pixel-art top-down sprite ────────────────────────────── */
character(founder,dir,moving,time,jumpHeight=0,isSprinting=false,sitting=false){
  const ctx=this.ctx, S=this.scale, T=TILE_SIZE*S;
  const p=this.sp(founder.x,founder.y);
  // Jump: lift the sprite up (in isometric: up-left = higher z)
  const jumpOffsetY = Math.round(jumpHeight * S * TILE_SIZE * 0.5 / TILE_SIZE * 2);
  const cx=Math.round(p.x+T/2), cy=Math.round(p.y+T/2) - jumpOffsetY;

  /* helper: draw one "pixel" of the sprite, offset from character center */
  const r=(color,dx,dy,w,h)=>
    px(ctx,color,cx+Math.round(dx*S),cy+Math.round(dy*S),Math.round(w*S)||1,Math.round(h*S)||1);

  /* ── SEATED pose ──────────────────────────────────────────────────── */
  if(sitting){
    /* ground shadow */
    ctx.globalAlpha=0.15; ctx.fillStyle='#000';
    ctx.beginPath();
    ctx.ellipse(cx, cy+Math.round(S*6), Math.round(S*6), Math.round(S*2.2), 0, 0, Math.PI*2);
    ctx.fill(); ctx.globalAlpha=1;

    /* legs extended horizontally (sitting, facing right) */
    r(C.pants, -5.5, 3.0, 4.5, 2.2);  /* left thigh */
    r(C.pants,  0.5, 3.0, 4.5, 2.2);  /* right thigh */
    r(C.shoe,  -6.5, 3.2, 2.5, 1.8);  /* left foot */
    r(C.shoe,   4.5, 3.2, 2.5, 1.8);  /* right foot */

    /* body / shirt — slightly raised, reclined */
    r(C.shirtD, -2.8, -4.2, 6.2, 6.5);
    r(C.shirt,  -3.0, -4.8, 6.2, 6.5);
    r('rgba(255,255,255,0.18)', -2.5, -4.8, 5.2, 1.5);
    r(C.skin,   -1.0, -5.0, 2.5, 1.8); /* collar */

    /* arms resting on armrests */
    r(C.shirt, -5.5, -3.5, 2.2, 4.0); /* left arm */
    r(C.skin,  -5.5,  0.2, 2.2, 1.8); /* left hand */
    r(C.shirt,  3.5, -3.5, 2.2, 4.0); /* right arm */
    r(C.skin,   3.5,  0.2, 2.2, 1.8); /* right hand */

    /* neck */
    r(C.skin, -1.0, -5.5, 2.5, 1.5);
    /* head shadow */
    r(C.skinD, -3.8, -14.2, 8.2, 9.5);
    /* head */
    r(C.skin, -4.0, -14.8, 8.2, 9.5);
    /* hair */
    r(C.hair, -4.0, -14.8, 8.2, 3.0);
    r(C.hair, -4.0, -14.8, 1.5, 9.5);
    r(C.hair,  2.8, -14.8, 1.5, 9.5);
    r('rgba(255,255,255,0.14)', -2.5, -14.8, 3.5, 1.5);
    /* face — eyes half-closed/relaxed */
    r(C.eyeW, -2.0, -9.2, 2.8, 1.6); /* left eye (narrowed) */
    r(C.eyeW,  1.2, -9.2, 2.8, 1.6); /* right eye (narrowed) */
    r(C.eye,  -1.5, -9.0, 1.8, 1.0);
    r(C.eye,   1.7, -9.0, 1.8, 1.0);
    r('rgba(255,255,255,0.9)', -0.7, -9.2, 0.9, 0.9);
    r('rgba(255,255,255,0.9)',  2.5, -9.2, 0.9, 0.9);
    /* nose */
    r(C.skinD, 0.0, -7.5, 1.2, 1.2);
    /* smile — slightly pleased expression */
    r(C.skinD, -1.2, -5.8, 3.2, 1.0);
    r(C.skinD, -1.2, -6.2, 0.8, 0.8);
    r(C.skinD,  1.8, -6.2, 0.8, 0.8);

    /* name tag */
    ctx.save();
    const tagY=cy+Math.round(S*(-18.5));
    ctx.font='bold '+Math.max(7,Math.round(S*5))+'px "Courier New",monospace';
    ctx.textAlign='center'; ctx.textBaseline='middle';
    const tw=Math.round(ctx.measureText('ALEX').width+S*6), th=Math.round(S*7);
    px(ctx,'rgba(8,12,18,0.85)', cx-Math.round(tw/2), tagY-Math.round(th/2), tw, th);
    ox(ctx,'rgba(100,180,255,0.65)', cx-Math.round(tw/2), tagY-Math.round(th/2), tw, th, 1);
    ctx.fillStyle='#a8d8ff'; ctx.fillText('ALEX',cx,tagY);
    ctx.restore();

    /* subtle "zzz" hint while resting */
    if(!this.reducedMotion){
      const pulse=0.5+Math.sin(time/800)*0.3;
      ctx.save();
      ctx.globalAlpha=pulse;
      ctx.font='bold '+Math.max(6,Math.round(S*3.5))+'px sans-serif';
      ctx.fillStyle='rgba(180,200,255,0.9)';
      ctx.textAlign='left'; ctx.textBaseline='alphabetic';
      const zx=Math.round(cx+Math.round(S*5)), zy=Math.round(cy+Math.round(S*(-16)));
      ctx.fillText('z',zx,zy);
      ctx.font='bold '+Math.max(5,Math.round(S*2.8))+'px sans-serif';
      ctx.fillText('z',zx+Math.round(S*4),zy-Math.round(S*2.5));
      ctx.font='bold '+Math.max(4,Math.round(S*2.2))+'px sans-serif';
      ctx.fillText('z',zx+Math.round(S*7.5),zy-Math.round(S*4.5));
      ctx.globalAlpha=1;
      ctx.restore();
    }
    return; // skip the standing pose below
