// ── Sofa sitting: block all movement, recover energy, handle recline ────
if (sittingOnSofa) {
  // Up arrow / W = recline further; Down arrow / S = sit back up
  const reclining  = keys.has('arrowup')   || keys.has('w');
  const uprighting = keys.has('arrowdown') || keys.has('s');
  const RECLINE_SPEED = 0.9; // full travel in ~1.1 s
  if (reclining || uprighting) {
    const prev = sofaRecline;
    sofaRecline = Math.max(0, Math.min(1, sofaRecline + (reclining ? 1 : -1) * RECLINE_SPEED * dt));
    // Toast at the limits (once per crossing)
    if (reclining  && prev < 1 && sofaRecline >= 1) toast('😴 Fully reclined. Pure bliss.');
    if (uprighting && prev > 0 && sofaRecline <= 0) toast('🛋️ Back upright. Almost like working.');
  }
  sofaRestAccumulator += dt;
  if (sofaRestAccumulator >= 2) {
    sofaRestAccumulator %= 2;
    changeEnergy(+2);
    updateUI();
    if (state.energy >= 100) {
      standUpFromSofa();
      toast('🧍 Fully recharged! Back to it.');
      return moving;
    }
  }
  return moving; // no movement while sitting
}

