      ctx.fillText('z',zx,zy);
      ctx.font='bold '+Math.max(5,Math.round(S*2.8*zScale))+'px sans-serif';
      ctx.fillText('z',zx+Math.round(S*4*zScale),zy-Math.round(S*2.5*zScale));
