222 | export function parseSave(raw) {
223 |   const fresh = newState();
224 |   try {
225 |     const value = JSON.parse(raw);
226 |     if (!value || value.version !== 2) return fresh;
227 |     if (value.founder && isWalkable(value.founder.x, value.founder.y)) fresh.founder = { x: value.founder.x, y: value.founder.y };
228 |     if (Number.isFinite(value.energy)) fresh.energy = Math.max(0, Math.min(100, value.energy));
229 |     if (Number.isFinite(value.minutes)) fresh.minutes = Math.max(540, Math.min(1079, value.minutes));
230 |     if (Number.isFinite(value.distance)) fresh.distance = Math.max(0, Math.min(100000, value.distance));
231 |     if (Array.isArray(value.completed)) fresh.completed = TASKS.filter((id) => id !== 'sleep' && value.completed.includes(id));
232 |     fresh.sound = value.sound === true;
233 |     fresh.lightOn = value.lightOn !== false; // default to true if missing
234 |     fresh.lampOn = value.lampOn !== false;   // default to true if missing
235 |     if (Number.isFinite(value.day)) fresh.day = Math.max(1, Math.min(10, value.day));
236 |     return fresh;
237 |   } catch { return fresh; }
