911 |   /* minutes: 540 (9 AM) → 1079 (5:59 PM).  Paints a translucent wash over  */
912 |   /* the whole room so the light gradually shifts from warm morning gold      */
913 |   /* through neutral midday, amber afternoon, and finally deep dusk blue.     */
914 |   _skyOverlay(minutes){
915 |     const ctx=this.ctx, S=this.scale, T=TILE_SIZE*S;
916 |     const tl=this.sp(0,0);
917 |     const rw=ROOM.width*T, rh=ROOM.depth*T;
918 | 
919 |     // Normalise to [0,1]: 9 AM = 0, ~6 PM = 1
920 |     const t=Math.max(0,Math.min(1,(minutes-540)/539));
921 | 
922 |     // Colour key-frames: [t, r, g, b, a]
923 |     const stops=[
924 |       [0.00, 255, 200,  80, 0.12],  // 9 AM  – warm morning gold
925 |       [0.22, 255, 245, 200, 0.00],  // noon  – neutral (no tint)
926 |       [0.55, 255, 160,  50, 0.07],  // 3 PM  – amber afternoon
927 |       [0.80,  80,  60, 160, 0.20],  // 5 PM  – dusk violet
928 |       [1.00,  15,  22,  70, 0.40],  // 6 PM  – deep evening blue
929 |     ];
930 | 
931 |     // Find surrounding stops and lerp
932 |     let lo=stops[0], hi=stops[stops.length-1];
933 |     for(let i=0;i<stops.length-1;i++){
934 |       if(t>=stops[i][0] && t<=stops[i+1][0]){ lo=stops[i]; hi=stops[i+1]; break; }
935 |     }
936 |     const u= lo[0]===hi[0] ? 0 : (t-lo[0])/(hi[0]-lo[0]);
937 |     const lerp=(a,b)=>a+( b-a)*u;
938 |     const r=Math.round(lerp(lo[1],hi[1]));
939 |     const g=Math.round(lerp(lo[2],hi[2]));
940 |     const b=Math.round(lerp(lo[3],hi[3]));
941 |     const a=lerp(lo[4],hi[4]);
942 |     if(a<0.005) return; // nothing to draw at pure midday
943 | 
944 |     // Tint the whole room (walls + floor)
945 |     ctx.globalAlpha=a;
946 |     px(ctx,`rgb(${r},${g},${b})`,tl.x,tl.y-T*3,rw,rh+T*3);
947 |     ctx.globalAlpha=1;
