949 |     // Extra wall-top gradient: walls feel more saturated than the floor
950 |     const wallAlpha=a*0.55;
951 |     if(wallAlpha>0.003){
952 |       const wGrad=ctx.createLinearGradient(0,tl.y-T*3,0,tl.y+T);
953 |       wGrad.addColorStop(0,`rgba(${r},${g},${b},${wallAlpha.toFixed(3)})`);
954 |       wGrad.addColorStop(1,`rgba(${r},${g},${b},0)`);
955 |       ctx.fillStyle=wGrad;
