962 |       const mx=tl.x+rw*0.85, my=tl.y-T*2;
963 |       const moonR=Math.round(T*2.2);
964 |       const moonGrad=ctx.createRadialGradient(mx,my,0,mx,my,moonR);
965 |       moonGrad.addColorStop(0,`rgba(200,220,255,${(0.22*moonStrength).toFixed(3)})`);
966 |       moonGrad.addColorStop(1,'rgba(200,220,255,0)');
