/* ── Natural window light shafts ─────────────────────────────────────── */
/* Called only when the overhead lights are off.  Draws angled beams of   */
/* sunlight (daytime) or moonlight (evening) coming through back-wall and  */
/* left-wall windows, using clipped parallelogram paths + linear gradients.*/
_windowLight(minutes,time){
  const ctx=this.ctx, S=this.scale, T=TILE_SIZE*S;
  const tl=this.sp(0,0);
  const rw=ROOM.width*T, rh=ROOM.depth*T;

  // t: 0 = 9 AM, 1 = 6 PM
  const t=Math.max(0,Math.min(1,(minutes-540)/539));
  // isNight: evening when t > 0.67 (~4 PM onwards)
  const isNight=t>0.67;
  // flicker: gentle alive shimmer in the shafts
  const flicker=0.92+Math.sin(time/900)*0.06+Math.sin(time/370)*0.02;

  // ── Shaft colour & intensity ──────────────────────────────────────────
  // Day: warm golden sun; intensity peaks at morning, dims into afternoon
  // Night: cool silver-blue moon; fades in once dark
  let shR,shG,shB,shaftAlpha;
  if(!isNight){
    // Morning-gold → afternoon-amber. t=0→0.67
    const dayT=t/0.67;
    shR=255; shG=Math.round(210-dayT*30); shB=Math.round(100-dayT*60);
    // Bright at sunrise, eases at midday, modest in afternoon
    shaftAlpha=(0.28-dayT*0.10)*flicker;
  } else {
    // Moon: fades in as evening deepens. nightT: 0→1 over t=0.67→1
    const nightT=(t-0.67)/0.33;
    shR=180; shG=200; shB=255;
    shaftAlpha=(0.10+nightT*0.14)*flicker;
  }

  // Helper: draw one parallelogram shaft clipped + gradient-filled.
  // wx,wy = top-centre of shaft origin (screen px); width = half-width at top;
  // slant = how far right the bottom edge shifts vs top;
  // len = shaft length in pixels; colour stops built from shR/G/B.
  const drawShaft=(wx,wy,halfW,slant,len)=>{
    const topL=wx-halfW, topR=wx+halfW;
    const botL=topL+slant, botR=topR+slant;
    ctx.save();
    ctx.beginPath();
    ctx.moveTo(topL,wy);
    ctx.lineTo(topR,wy);
    ctx.lineTo(botR+halfW*0.4,wy+len);  // slight bloom at base
    ctx.lineTo(botL-halfW*0.4,wy+len);
    ctx.closePath();
    ctx.clip();
    const grad=ctx.createLinearGradient(wx,wy,wx+slant*0.5,wy+len);
    grad.addColorStop(0,  `rgba(${shR},${shG},${shB},${(shaftAlpha*0.9).toFixed(3)})`);
    grad.addColorStop(0.35,`rgba(${shR},${shG},${shB},${(shaftAlpha*0.55).toFixed(3)})`);
    grad.addColorStop(0.7, `rgba(${shR},${shG},${shB},${(shaftAlpha*0.18).toFixed(3)})`);
    grad.addColorStop(1,   `rgba(${shR},${shG},${shB},0)`);
    ctx.fillStyle=grad;
    ctx.fillRect(topL-Math.abs(slant)-halfW,wy,
                 Math.abs(topR-topL)+Math.abs(slant)+halfW*2,len+1);
    ctx.restore();
  };

  // ── Back-wall windows (y=0, top wall) ────────────────────────────────
  // The back wall is the strip from tl.y-T*3 to tl.y.
  // Windows sit in the wall; shafts originate from just above tl.y
  // and fall forward (downward on screen) at an angle.
  // Day: sun comes from upper-left → shafts slant right
  // Night: moon is higher/right → shafts nearly vertical, cooler
  const wallY=tl.y-T*0.5; // shaft origins just inside top of floor area
  const shaftLen=Math.round(rh*0.72);
  const daySlant =Math.round(T*2.2);   // slant rightward (sun from left)
  const nightSlant=Math.round(T*0.6);  // nearly vertical (moon overhead)
  const slant=isNight?nightSlant:daySlant;

  // Three back-wall windows: left zone, centre, right zone
  // Placed to avoid the board (x4-8), lightswitch (x15), and plants
  // Back-wall window 1: x≈1.8 (left of plan board)
  const w1=this.sp(1.8,0); drawShaft(w1.x,wallY,Math.round(T*0.8),slant,shaftLen);
  // Back-wall window 2: x≈9.5 (between board and workstation)
  const w2=this.sp(9.5,0); drawShaft(w2.x,wallY,Math.round(T*0.9),slant,shaftLen);
  // Back-wall window 3: x≈12.5 (right section above backplant area)
  const w3=this.sp(12.5,0); drawShaft(w3.x,wallY,Math.round(T*0.7),slant,shaftLen);

  // ── Left-wall window (x=0, side wall) ────────────────────────────────
  // The left skirting strip runs from tl.x-S*3 downward.
  // Shaft comes from the left, fans rightward across the floor.
  // Day only — moonlight on the left wall would be rare; skip at night.
  if(!isNight){
    // Left wall window at y≈5 (mid-room), shaft fans right across floor
    const lwp=this.sp(0,5.5);
    const lwHalf=Math.round(T*0.65);
    // Left-wall shaft: origin is at the left edge, beam goes right
    // We rotate context to draw it sideways then restore
    ctx.save();
    ctx.translate(lwp.x,lwp.y);
    ctx.rotate(-Math.PI*0.04); // very slight tilt down
    const lwLen=Math.round(rw*0.48);
    const lwGrad=ctx.createLinearGradient(0,0,lwLen,0);
    lwGrad.addColorStop(0,   `rgba(${shR},${shG},${shB},${(shaftAlpha*0.85).toFixed(3)})`);
    lwGrad.addColorStop(0.4, `rgba(${shR},${shG},${shB},${(shaftAlpha*0.40).toFixed(3)})`);
    lwGrad.addColorStop(0.75,`rgba(${shR},${shG},${shB},${(shaftAlpha*0.10).toFixed(3)})`);
    lwGrad.addColorStop(1,   `rgba(${shR},${shG},${shB},0)`);
    ctx.beginPath();
    ctx.moveTo(0,-lwHalf); ctx.lineTo(lwLen,-lwHalf*1.6);
    ctx.lineTo(lwLen, lwHalf*1.6); ctx.lineTo(0, lwHalf);
    ctx.closePath();
    ctx.clip();
    ctx.fillStyle=lwGrad;
    ctx.fillRect(0,-lwHalf*2,lwLen+1,lwHalf*4);
    ctx.restore();
  }

  // ── Window-sill highlight on back wall ────────────────────────────────
  // A thin bright strip at the base of each back-wall window opening to
  // sell the idea that there's actual glass/frame up there.
  const sillH=Math.max(2,Math.round(S*1.5));
  const sillY=Math.round(tl.y-T*1.0);
  const sillAlpha=isNight?(shaftAlpha*1.2):(shaftAlpha*1.5);
  // sill 1
  const sw1=Math.round(T*1.6); const sx1=this.sp(1.8,0).x-Math.round(sw1/2);
  ctx.globalAlpha=Math.min(0.9,sillAlpha); px(ctx,`rgb(${shR},${shG},${shB})`,sx1,sillY,sw1,sillH);
  // sill 2
  const sw2=Math.round(T*1.8); const sx2=this.sp(9.5,0).x-Math.round(sw2/2);
  px(ctx,`rgb(${shR},${shG},${shB})`,sx2,sillY,sw2,sillH);
  // sill 3
  const sw3=Math.round(T*1.4); const sx3=this.sp(12.5,0).x-Math.round(sw3/2);
  px(ctx,`rgb(${shR},${shG},${shB})`,sx3,sillY,sw3,sillH);
  ctx.globalAlpha=1;

  // ── Ambient floor reflection pools ────────────────────────────────────
  // Where each shaft hits the floor, a soft radial glow shows the
  // reflected light bouncing off the floorboards.
  const poolAlpha=shaftAlpha*0.45;
  const poolBeam=(wx,beamSlant)=>{
    // Pool centre: shaft travels ~60% of shaftLen before fading
    const px2=wx+beamSlant*0.6;
    const py2=wallY+shaftLen*0.55;
    const poolR=Math.round(T*1.4);
    const pg=ctx.createRadialGradient(px2,py2,0,px2,py2,poolR);
    pg.addColorStop(0,`rgba(${shR},${shG},${shB},${(poolAlpha).toFixed(3)})`);
    pg.addColorStop(1,`rgba(${shR},${shG},${shB},0)`);
    ctx.fillStyle=pg;
    ctx.fillRect(px2-poolR,py2-poolR,poolR*2,poolR*2);
  };
  poolBeam(w1.x,slant); poolBeam(w2.x,slant); poolBeam(w3.x,slant);
}

  /* ── Darkness overlay when lights are off ── */
  if(!lightOn){
    const S=this.scale, T=TILE_SIZE*S;
    const tl=this.sp(0,0);
    const rw=ROOM.width*T, rh=ROOM.depth*T;
    /* deep dark base over the whole room */
    ctx.globalAlpha=0.86;
    px(ctx,'#04070a',tl.x,tl.y-T*3,rw,rh+T*3);
    ctx.globalAlpha=1;
    /* natural window light shafts cut through the dark */
    this._windowLight(minutes,time);
