clockAccumulator += dt;
saveAccumulator += dt;
energyDrainAccumulator += dt;
electricDrainAccumulator += dt;
if (clockAccumulator >= 3) { state.minutes = Math.min(1079, state.minutes + 1);clockAccumulator %= 3;updateUI(); }
if (saveAccumulator >= 2) { saveAccumulator %= 2;save(); }
// Drain 1 energy per drainInterval real-seconds (coffee speeds this up; sleep stops it)
if (energyDrainAccumulator >= drainInterval) {
  energyDrainAccumulator %= drainInterval;
  if (!state.completed.includes('sleep')) {
    changeEnergy(-1);
    updateUI();
    if (state.energy <= 20 && !lowEnergyWarned) {
      lowEnergyWarned = true;
      toast('⚠️ Running low on stamina. Grab a coffee — or finish your tasks and sleep!');
    }
    if (state.energy <= 0) { burnOut(); return moving; }
  }
}
// ── Electricity drain ────────────────────────────────────────────────────
// Base drain from always-on devices; lights and lamp add to it.
// Rate is computed in units of "electricity per real second":
//   - base idle draw (router, standby devices): 0.04 / s  → ~100 in ~41 min
//   - ceiling lights on:                      + 0.10 / s
//   - floor lamp on:                          + 0.04 / s
// Total with both lights on: 0.18/s → 100 drains in ~9.3 min (one game day)
const elecRate = 0.04
  + (state.lightOn ? 0.10 : 0)
  + (state.lampOn  ? 0.04 : 0);
const elecDrain = elecRate * dt;
if (elecDrain > 0 && state.elec > 0) {
  changeElec(-elecDrain);
  updateUI();
  if (state.elec <= 20 && !lowElecWarned) {
    lowElecWarned = true;
    toast('⚡ Power running low! Turn off lights to conserve electricity.');
  }
  if (state.elec <= 0) {
    // Blackout: force lights off, warn the player
    if (state.lightOn || state.lampOn) {
      state.lightOn = false;
      state.lampOn = false;
      toast('🔌 Blackout! You\'ve run out of electricity. Lights off.');
      save();
    }
  }
}
return moving;

