 48 | export function canTravel(from, to, objects = OBJECTS) {
 49 |   const steps = Math.max(1, Math.ceil(Math.hypot(to.x - from.x, to.y - from.y) / 0.07));
 50 |   for (let i = 0; i <= steps; i++) {
 51 |     const t = i / steps;
 52 |     if (!isWalkable(from.x + (to.x - from.x) * t, from.y + (to.y - from.y) * t, objects)) return false;
 53 |   }
 54 |   return true;
 55 | }
