 57 | // A* on a quarter-tile grid, followed by collision-tested line-of-sight smoothing.
 58 | export function nearestWalkable(tx, ty, objects = OBJECTS) {
 59 |   if (isWalkable(tx, ty, objects)) return { x: tx, y: ty };
 60 |   // Spiral outward in quarter-tile steps until we find a walkable point
 61 |   const step = 0.25;
 62 |   for (let r = step; r <= 3; r += step) {
 63 |     let best = null, bestDist = Infinity;
 64 |     const n = Math.ceil((r * 2) / step);
 65 |     for (let i = 0; i <= n; i++) {
 66 |       const t = i / n;
 67 |       for (const [cx, cy] of [
 68 |         [tx - r + t * r * 2, ty - r],
 69 |         [tx + r, ty - r + t * r * 2],
 70 |         [tx + r - t * r * 2, ty + r],
 71 |         [tx - r, ty + r - t * r * 2],
 72 |       ]) {
 73 |         const rx = Math.round(cx / step) * step;
 74 |         const ry = Math.round(cy / step) * step;
 75 |         if (!isWalkable(rx, ry, objects)) continue;
 76 |         const d = Math.hypot(rx - tx, ry - ty);
 77 |         if (d < bestDist) { best = { x: rx, y: ry }; bestDist = d; }
 78 |       }
 79 |     }
 80 |     if (best) return best;
 81 |   }
 82 |   return null;
 83 | }
