 85 | export function findPath(from, to, objects = OBJECTS) {
 86 |   if (!isWalkable(from.x, from.y, objects) || !isWalkable(to.x, to.y, objects)) return null;
 87 |   if (canTravel(from, to, objects)) return [{ ...to }];
 88 |   const step = 0.25;
 89 |   const key = (x, y) => `${x},${y}`;
 90 |   const point = (node) => ({ x: node.x * step, y: node.y * step });
