@media(prefers-reduced-motion:reduce){*,*::before,*::after{animation:none !important;transition:none !important}}

/* ── Cycling overlay ─────────────────────────────────────────────────────── */
#cycling-overlay{
  position:fixed;bottom:56px;left:50%;transform:translateX(-50%);
  background:rgba(8,14,8,.96);
  border:2px solid #1a3a1a;
  border-radius:6px;
  padding:10px 16px 11px;
  min-width:260px;
  z-index:200;
  pointer-events:none;
  text-align:center;
  box-shadow:0 4px 24px rgba(0,0,0,.7);
}
.cycling-eyebrow{font-size:8px;letter-spacing:3px;color:#78c878;margin-bottom:4px;font-weight:700}
.cycling-charge-label{font-size:10px;letter-spacing:2px;color:#7a8a7a;margin-bottom:8px;height:14px;transition:color .2s}
.cycling-charge-label.charging{color:#40e870}
.cycling-charge-label.fast{color:#a0f040}
.cycling-charge-label.max{color:#f0e040;text-shadow:0 0 8px #f0e04088}
.cycling-bar-wrap{display:flex;align-items:center;gap:8px;margin-bottom:7px}
.pedal-track{
  flex:1;height:14px;
  background:#0a130a;
  border:2px solid #1a3a1a;
  border-radius:3px;
  overflow:visible;
  position:relative;
}
.pedal-fill{
  height:100%;width:0%;border-radius:2px;
  background:#2a3a2a;
  transition:width .08s linear, background .2s;
}
/* colour stages driven by JS class toggles */
.pedal-fill.charging{background:linear-gradient(90deg,#1a6a2a,#40e870)}
.pedal-fill.fast{background:linear-gradient(90deg,#3a8a1a,#a0f040)}
.pedal-fill.max{background:linear-gradient(90deg,#8a8010,#f0e040);box-shadow:0 0 8px #f0e04066}
/* threshold tick marks */
.pedal-tick{
  position:absolute;top:-3px;
  width:2px;height:calc(100% + 6px);
  background:#3a5a3a;
  transform:translateX(-50%);
  pointer-events:none;
}
.pedal-tick--fast{background:#5a7a2a}
.pedal-val{font-size:9px;color:#7a9a7a;min-width:22px;text-align:right;font-weight:700}
.cycling-hint{
  font-size:8px;letter-spacing:1px;color:#3a5a3a;
}
.cycling-hint kbd{
  display:inline-block;
  background:rgba(30,50,30,.9);
  border:1px solid #2a4a2a;
  border-bottom-width:2px;
  border-radius:2px;
  padding:1px 5px;
  font:inherit;font-size:7px;font-weight:700;
  color:#78c878;
  letter-spacing:1px;
}

