// ── Cycling: player is on the bike ───────────────────────────────────────
if (isCycling) {
  // Tick down breakdown cooldown
  if (bikeBreakdown > 0) {
    bikeBreakdown = Math.max(0, bikeBreakdown - dt);
    // While broken: drain power fast and give no charge
    pedalPower = Math.max(0, pedalPower - 30 * dt);
    if (bikeBreakdown <= 0) {
      pedalPower = 0;
      toast('✅ Bike recovered. Get pedaling!');
    }
    updateUI();
    return moving;
  }

  // Normal pedal power decay at 14 units/s
  pedalPower = Math.max(0, pedalPower - 14 * dt);

  // Charge rate tiers (elec units per real second):
  //   0–25   → no charge
  //   25–50  → 2 / s   (normal)
  //   50–75  → 4 / s   (double)
  //   75–100 → 6 / s   (triple)
  let chargeRate = 0;
  if (pedalPower >= 75) chargeRate = 6;
  else if (pedalPower >= 50) chargeRate = 4;
  else if (pedalPower >= 25) chargeRate = 2;

  if (chargeRate > 0 && state.elec < 100) {
    changeElec(chargeRate * dt);
    lowElecWarned = false; // reset warning so it re-fires if they drain it back down
  }
  updateUI();
  return moving; // no walking while cycling
}

