/* ── Cycling overlay ─────────────────────────────────────────────────────── */
#cycling-overlay{
  position:fixed;bottom:56px;left:50%;transform:translateX(-50%);
  background:rgba(8,14,8,.96);
  border:2px solid #1a3a1a;
  border-radius:6px;
  padding:10px 16px 11px;
  min-width:260px;
  z-index:200;
  pointer-events:none;
  text-align:center;
  box-shadow:0 4px 24px rgba(0,0,0,.7);
  transition:border-color .15s;
}
#cycling-overlay.overloaded{
  border-color:#c83030;
  animation:bike-shake .12s ease-in-out infinite;
}
@keyframes bike-shake{
  0%,100%{transform:translateX(-50%)}
  25%{transform:translateX(calc(-50% - 3px))}
  75%{transform:translateX(calc(-50% + 3px))}
}
.cycling-eyebrow{font-size:8px;letter-spacing:3px;color:#78c878;margin-bottom:4px;font-weight:700}
.cycling-charge-label{font-size:10px;letter-spacing:2px;color:#7a8a7a;margin-bottom:8px;height:14px;transition:color .15s}
.cycling-charge-label.normal{color:#40e870}
.cycling-charge-label.double{color:#a0f040}
.cycling-charge-label.triple{color:#f0e040;text-shadow:0 0 8px #f0e04088}
.cycling-charge-label.broken{color:#e84040;animation:broken-flash .4s ease-in-out infinite alternate}
@keyframes broken-flash{from{opacity:1}to{opacity:.4}}
.cycling-bar-wrap{display:flex;align-items:center;gap:8px;margin-bottom:7px}
.pedal-track{
  flex:1;height:14px;
  background:#0a130a;
  border:2px solid #1a3a1a;
  border-radius:3px;
  overflow:visible;
  position:relative;
}
.pedal-fill{
  height:100%;width:0%;border-radius:2px;
  background:#2a3a2a;
  transition:width .08s linear, background .2s;
}
/* colour stages driven by JS class toggles */
.pedal-fill.normal{background:linear-gradient(90deg,#1a6a2a,#40e870)}
.pedal-fill.double{background:linear-gradient(90deg,#3a8a1a,#a0f040)}
.pedal-fill.triple{background:linear-gradient(90deg,#8a8010,#f0e040);box-shadow:0 0 8px #f0e04066}
.pedal-fill.broken{background:linear-gradient(90deg,#6a1010,#e84040);animation:broken-fill-pulse .3s ease-in-out infinite alternate}
@keyframes broken-fill-pulse{from{box-shadow:0 0 6px #e8404066}to{box-shadow:0 0 16px #e84040cc}}
/* threshold tick marks */
.pedal-tick{
  position:absolute;top:-3px;
  width:2px;height:calc(100% + 6px);
  background:#2a4a2a;
  transform:translateX(-50%);
  pointer-events:none;
}
.pedal-tick--double{background:#4a6a1a}
.pedal-tick--triple{background:#7a7010}
.pedal-tick--danger{background:#8a2020;box-shadow:0 0 4px #e8404066}
.pedal-val{font-size:9px;color:#7a9a7a;min-width:22px;text-align:right;font-weight:700}
.cycling-hint{
  font-size:8px;letter-spacing:1px;color:#3a5a3a;
}
.cycling-hint kbd{
  display:inline-block;
  background:rgba(30,50,30,.9);
  border:1px solid #2a4a2a;
  border-bottom-width:2px;
  border-radius:2px;
  padding:1px 5px;
  font:inherit;font-size:7px;font-weight:700;
  color:#78c878;
